
window.VSim=window.VSim||{};(function(NS){
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const STOCK_KEYS=['food','wood','stone'];
NS.BUILDINGS.warehouse={label:'창고',icon:'📦',capacity:0,maint:.0035,storage:{food:260,wood:175,stone:165},desc:'이 정착지의 식량·목재·석재 저장 한도를 크게 늘립니다.'};
NS.BUILDINGS.trading_post={label:'교역소',icon:'⚖️',capacity:0,maint:.005,storage:{food:70,wood:55,stone:50},desc:'다른 마을의 교역소와 거래할 수 있는 교역 노드입니다.'};
if(NS.BUILDINGS.storehouse) NS.BUILDINGS.storehouse.label='구형 창고';
const TECH_EFFECTS={
 AGRICULTURE:['식량 채취량 +8%'], CARPENTRY:['목재 채취량 +12%'], MASONRY:['석재 채취량 +10%'],
 BARTER:['교역 가능 경로 +1.5','외곽 정착지에 교역소 건설 가능'], RECORD_KEEPING:['Knowledge 획득 +15%'],
 IRRIGATION:['고대 경작지 → 고대 농장 개축 해금'], GRANARY:['곡물창고 해금','곡물창고당 식량 저장 +180'],
 QUARRY:['채석장 해금','암지·산 채석장 석재 생산 +22%'], CART:['교역 가능 경로 +3','회당 운송량 +12'],
 MARKET:['교역량 +10','교역 수수료 -18%','교역 가능 경로 +0.8'], ROADS:['도로 타일 경로비 -28%','교역 수수료 -22%','교역 가능 경로 +3'],
 CURRENCY:['교역 수수료 -28%','교역량 +6','교역 가능 경로 +1.7'], SCHOLARSHIP:['Knowledge 획득 +32%']
};
for(const [id,e] of Object.entries(TECH_EFFECTS))if(NS.TECH[id])NS.TECH[id].effects=e;

function capsForTile(t){let c={food:45,wood:30,stone:25};for(const b of t.buildings||[]){const s=NS.BUILDINGS[b]?.storage||{};for(const k of STOCK_KEYS)c[k]+=s[k]||0;}return c;}
function ensureTileEconomy(t){if(!t.stocks)t.stocks={food:0,wood:0,stone:0};for(const k of STOCK_KEYS)if(!Number.isFinite(t.stocks[k]))t.stocks[k]=0;return t;}
NS.settlementCaps=capsForTile;

function attachVillage(v,w){v._world=w;v.tradeHistory=v.tradeHistory||[];v.logisticsStats=v.logisticsStats||{moves:0,foodMoved:0};for(const id of v.territory){const t=ensureTileEconomy(w.map.get(id));if(!t)continue;if(id===v.coreTileId){t.buildings=t.buildings.map(b=>b==='storehouse'?'warehouse':b);if(!t.buildings.includes('warehouse'))t.buildings.push('warehouse');if(!t.buildings.includes('trading_post'))t.buildings.push('trading_post');}}
}
function distributeLegacy(v,w){const core=ensureTileEconomy(w.map.get(v.coreTileId));if(!core)return;const legacy={food:Number(v.food)||0,wood:Number(v.wood)||0,stone:Number(v.stone)||0};for(const k of STOCK_KEYS){if((core.stocks[k]||0)<=0)core.stocks[k]=legacy[k];}for(const k of STOCK_KEYS){try{delete v[k]}catch(_){}}attachVillage(v,w);}
for(const k of STOCK_KEYS){try{Object.defineProperty(NS.Village.prototype,k,{configurable:true,get:function(){if(!this._world)return this['_legacy_'+k]||0;let n=0;for(const id of this.territory){const t=this._world.map.get(id);if(t)n+=(ensureTileEconomy(t).stocks[k]||0);}return n;},set:function(value){if(!this._world){this['_legacy_'+k]=Number(value)||0;return;}const target=Math.max(0,Number(value)||0),cur=this[k],delta=target-cur;if(Math.abs(delta)<1e-9)return;const core=ensureTileEconomy(this._world.map.get(this.coreTileId));if(delta>0){const cap=capsForTile(core)[k];core.stocks[k]=Math.min(cap*1.1,core.stocks[k]+delta);}else{let need=-delta;for(const id of [this.coreTileId,...[...this.territory].filter(x=>x!==this.coreTileId)]){const t=ensureTileEconomy(this._world.map.get(id));const take=Math.min(need,t.stocks[k]);t.stocks[k]-=take;need-=take;if(need<=0)break;}}}})}catch(e){}}

NS.Village.prototype.settlementCaps=function(tileId){const t=this._world?.map.get(tileId);return t?capsForTile(t):{food:0,wood:0,stone:0};};
NS.Village.prototype.settlementReserveDays=function(tileId){const t=this._world?.map.get(tileId);if(!t)return 0;const n=this.tileResidents(tileId).length;return n?ensureTileEconomy(t).stocks.food/Math.max(.12,n*.36):999;};
NS.Village.prototype.criticalFoodReserveDays=function(){const vals=[...this.territory].filter(id=>this.tileResidents(id).length).map(id=>this.settlementReserveDays(id));return vals.length?Math.min(...vals):0;};
NS.Village.prototype.foodReserveDays=function(){const vals=[...this.territory].filter(id=>this.tileResidents(id).length).map(id=>({n:this.tileResidents(id).length,d:this.settlementReserveDays(id)}));const pop=vals.reduce((a,x)=>a+x.n,0);return pop?vals.reduce((a,x)=>a+x.n*x.d,0)/pop:0;};
NS.Village.prototype.storageCaps=function(){let c={food:0,wood:0,stone:0};for(const id of this.territory){const t=this._world?.map.get(id);if(!t)continue;const q=capsForTile(t);for(const k of STOCK_KEYS)c[k]+=q[k];}return c;};
NS.Village.prototype.stockAt=function(tileId,k){const t=this._world?.map.get(tileId);return t?(ensureTileEconomy(t).stocks[k]||0):0;};
NS.Village.prototype.depositAt=function(tileId,k,amount){const t=this._world?.map.get(tileId);if(!t)return 0;ensureTileEconomy(t);const cap=capsForTile(t)[k],room=Math.max(0,cap-t.stocks[k]),put=Math.min(room,Math.max(0,amount));t.stocks[k]+=put;return put;};
NS.Village.prototype.withdrawAt=function(tileId,k,amount){const t=this._world?.map.get(tileId);if(!t)return 0;ensureTileEconomy(t);const take=Math.min(t.stocks[k],Math.max(0,amount));t.stocks[k]-=take;return take;};
NS.Village.prototype.withdrawNetwork=function(k,amount,preferId=null){let need=amount,got=0;const ids=[preferId,...[...this.territory].filter(x=>x!==preferId)].filter(x=>x!=null);for(const id of ids){const q=this.withdrawAt(id,k,need);got+=q;need-=q;if(need<=0)break;}return got;};
NS.Village.prototype.tradingPosts=function(){return [...this.territory].filter(id=>this._world?.map.get(id)?.hasBuilding('trading_post'));};
NS.Village.prototype.warehouseCount=function(){return [...this.territory].filter(id=>this._world?.map.get(id)?.hasBuilding('warehouse')).length;};
NS.Village.prototype.tradePressure=function(){const d=this.criticalFoodReserveDays(),shortFood=Math.max(0,35-d)/35;let storage=0;for(const id of this.territory){const t=this._world.map.get(id),c=capsForTile(t);storage=Math.max(storage,(t.stocks.food/c.food)-.9,(t.stocks.wood/c.wood)-.9,(t.stocks.stone/c.stone)-.9);}return clamp(Math.max(shortFood,storage,0),0,1.6);};

// Local consumption and local production.
NS.Person.prototype.metabolism=function(v,w,worked=true){const t=this.homeTile(v,w);this.hunger=clamp(this.hunger+(worked?(5+Math.random()*3):(4+Math.random()*2)),0,100);this.energy=clamp(this.energy-(worked?(8+Math.random()*5):(4+Math.random()*3)),0,100);const need=this.age<15?.25:.36,ate=v.withdrawAt(t.id,'food',need)>=need*.8;if(ate)this.hunger=clamp(this.hunger-(5+Math.random()*3),0,100);this.energy=clamp(this.energy+(worked?(8+Math.random()*5):(10+Math.random()*5)),0,100);this.energy+=(82-this.energy)*.035;let hd=(82-this.health)*.002;if(!ate)hd-=1.0;if(this.hunger>80)hd-=.65;if(this.age>60)hd-=.035;this.health=clamp(this.health+hd,0,100);this.happiness+=(65-this.happiness)*.0025;if(!ate)this.happiness-=.18;this.happiness=clamp(this.happiness,0,100);};
const oldAct=NS.Person.prototype.act;
NS.Person.prototype.act=function(v,w){if(!this.alive)return;if(this.assignment==='PIONEER'){this.currentAction='개척지에서 작업 중';this.metabolism(v,w,true);v.gainKnowledge(this.knowledgeYield()*.8,w,this.job);return;}this.chooseJob(v,w);const t=this.homeTile(v,w);if(this.age<15){this.currentAction='정착지에서 생활 중';this.metabolism(v,w,false);v.gainKnowledge(this.knowledgeYield(),w,'생활');return;}const day=w.ordinalDay();let got=0;if(this.job==='농부'){this.currentAction='정착지 주변에서 식량 생산 중';got=NS.V034D3A.harvestAndStore(this,v,w,t,'food',.9+this.skills.farming/70,day);}else if(this.job==='채집꾼'||this.job==='사냥꾼'){this.currentAction='야생 식량을 확보 중';got=NS.V034D3A.harvestAndStore(this,v,w,t,'food',.5+this.skills.hunting/100,day);}else if(this.job==='목수'){this.currentAction='목재 채취 중';got=NS.V034D3A.harvestAndStore(this,v,w,t,'wood',.55+this.skills.building/78,day);}else if(this.job==='광부'){this.currentAction='석재와 광맥을 채굴 중';got=NS.V034D3A.harvestAndStore(this,v,w,t,'stone',.42+this.skills.mining/85,day);if(t.resources.gold>0)v.gold+=t.harvest('gold',.015+this.skills.mining/650,day);}else if(this.job==='상인')this.currentAction='교역소와 가격을 살피는 중';else if(this.job==='건축가')this.currentAction='건물과 창고를 점검 중';else if(this.job==='경비')this.currentAction='정착지를 순찰 중';else this.currentAction='일거리를 찾는 중';this.metabolism(v,w,true);v.gainKnowledge(this.knowledgeYield(),w,this.job);};

// Settlement development: warehouses + trading posts.
NS.Village.prototype.payBuild=function(tileId,cost){if(this.gold<(cost.gold||0))return false;for(const k of STOCK_KEYS)if(this[k]<(cost[k]||0))return false;this.gold-=cost.gold||0;for(const k of STOCK_KEYS)this.withdrawNetwork(k,cost[k]||0,tileId);return true;};
NS.Village.prototype.developSettlements=function(w){for(const id of this.territory){const t=w.map.get(id),pop=this.tileResidents(id).length;if(!t||!pop)continue;const cap=t.buildings.reduce((a,b)=>a+(NS.BUILDINGS[b]?.capacity||0),0);if(pop>=Math.max(2,cap-1)&&!this.expansionProject&&this.payBuild(id,{wood:18,stone:6,gold:3}))t.addBuilding('house');const c=capsForTile(t),nearFull=Math.max(t.stocks.food/c.food,t.stocks.wood/c.wood,t.stocks.stone/c.stone)>.78;if(nearFull&&!t.hasBuilding('warehouse')&&this.payBuild(id,{wood:28,stone:16,gold:6})){t.addBuilding('warehouse');w.log(`${this.name}의 (${t.x},${t.y}) 정착지에 창고가 건설되었습니다.`,false,'BUILDING_BUILT',{village:this.name,tileId:id,building:'warehouse'});}if(id!==this.coreTileId&&pop>=3&&this.hasTech('BARTER')&&!t.hasBuilding('trading_post')&&this.payBuild(id,{wood:24,stone:8,gold:10})){t.addBuilding('trading_post');w.log(`${this.name}의 (${t.x},${t.y}) 정착지에 교역소가 문을 열었습니다.`,true,'BUILDING_BUILT',{village:this.name,tileId:id,building:'trading_post'});}}};

// Wrap seasonal tick for development.
const oldSeason=NS.Village.prototype.seasonalTick;NS.Village.prototype.seasonalTick=function(w){oldSeason.call(this,w);this.developSettlements(w);};

// Settlement-based logistics.
NS.World.prototype.processInternalLogistics=function(){for(const v of this.activeVillages){const occupied=[...v.territory].filter(id=>v.tileResidents(id).length);if(occupied.length<2)continue;for(const rid of occupied){const rdays=v.settlementReserveDays(rid);if(rdays>=24)continue;const donors=occupied.filter(id=>id!==rid&&v.settlementReserveDays(id)>55).sort((a,b)=>v.settlementReserveDays(b)-v.settlementReserveDays(a));if(!donors.length)continue;const did=donors[0],donor=v.stockAt(did,'food'),needPop=v.tileResidents(rid).length,need=Math.max(0,needPop*.36*38-v.stockAt(rid,'food')),qty=Math.min(16,need,Math.max(0,donor-v.tileResidents(did).length*.36*45));if(qty<1)continue;v.withdrawAt(did,'food',qty);v.depositAt(rid,'food',qty);v.logisticsStats.moves++;v.logisticsStats.foodMoved+=qty;if(qty>=5)this.telemetry.record('INTERNAL_LOGISTICS',this,{village:v.name,resource:'food',qty:+qty.toFixed(1),fromTileId:did,toTileId:rid});}}};

// Trading-post-only routing.
NS.World.prototype.routeInfo=function(a,b){const A=a.tradingPosts(),B=b.tradingPosts();if(!A.length||!B.length)return{reachable:false,cost:Infinity,range:Math.min(a.tradeRange(this),b.tradeRange(this)),sourceTileId:null,targetTileId:null};let best={cost:Infinity,sourceTileId:null,targetTileId:null};for(const x of A)for(const y of B){const c=this.map.tradePathCost([x],[y],new Set(this.activeVillages.filter(v=>v.hasTech('ROADS')).map(v=>v.id)));if(c<best.cost)best={cost:c,sourceTileId:x,targetTileId:y};}const range=Math.min(a.tradeRange(this),b.tradeRange(this));return{...best,range,reachable:Number.isFinite(best.cost)&&best.cost<=range};};
NS.World.prototype.dealCandidate=function(buyer,seller,resource,route){if(!route.reachable)return null;const bt=ensureTileEconomy(this.map.get(route.sourceTileId)),st=ensureTileEconomy(this.map.get(route.targetTileId));const bc=capsForTile(bt),sc=capsForTile(st),bpop=buyer.tileResidents(bt.id).length||1,spop=seller.tileResidents(st.id).length||1;let need=0,excess=0;if(resource==='food'){need=Math.max(0,bpop*.36*38-bt.stocks.food);excess=Math.max(0,st.stocks.food-spop*.36*55);}else{need=Math.max(0,bc[resource]*.38-bt.stocks[resource]);excess=Math.max(0,st.stocks[resource]-sc[resource]*.58);}let qty=Math.min(need,excess,buyer.merchantCapacity(),seller.merchantCapacity());if(qty<1.5)return null;const base={food:.34,wood:.28,stone:.42}[resource],scarcity=1+Math.min(1,need/Math.max(1,bt.stocks[resource]+need)*.35),unit=base*scarcity,feeMult=(buyer.tradeFeeMultiplier()+seller.tradeFeeMultiplier())/2,transportUnit=route.cost*.018*feeMult,budget=Math.max(0,buyer.gold-5);qty=Math.min(qty,budget/Math.max(.01,unit+transportUnit));if(qty<1.5)return null;const price=qty*unit,fee=qty*transportUnit+.2*route.cost*feeMult;return{buyer,seller,resource,qty,price,fee,total:price+fee*.55,routeCost:route.cost,sourceTileId:route.sourceTileId,targetTileId:route.targetTileId,score:need*(resource==='food'?1.4:1)+excess*.12};};
NS.World.prototype.executeTrade=function(d){const{buyer,seller,resource,qty,price,fee,total,routeCost,sourceTileId,targetTileId}=d;if(buyer.gold<total)return false;const taken=seller.withdrawAt(targetTileId,resource,qty),put=buyer.depositAt(sourceTileId,resource,taken);if(put<1)return false;if(put<taken)seller.depositAt(targetTileId,resource,taken-put);const scale=put/qty,realPrice=price*scale,realFee=fee*scale,realTotal=realPrice+realFee*.55;buyer.gold-=realTotal;seller.gold+=realPrice;for(const [v,imp,exp] of [[buyer,put,0],[seller,0,put]]){v.tradeStats.count++;v.tradeStats.imports+=imp;v.tradeStats.exports+=exp;}buyer.tradeStats.goldSpent+=realTotal;seller.tradeStats.goldEarned+=realPrice;const row={day:this.ordinalDay(),time:this.timestamp(),buyerId:buyer.id,buyer:buyer.name,sellerId:seller.id,seller:seller.name,resource,qty:+put.toFixed(2),price:+realPrice.toFixed(2),fee:+realFee.toFixed(2),routeCost:+routeCost.toFixed(2),buyerTileId:sourceTileId,sellerTileId:targetTileId};buyer.tradeHistory.push(row);seller.tradeHistory.push(row);buyer.tradeHistory=buyer.tradeHistory.slice(-25);seller.tradeHistory=seller.tradeHistory.slice(-25);this.recentTrades.push(row);this.recentTrades=this.recentTrades.filter(x=>this.ordinalDay()-x.day<=90);const label={food:'식량',wood:'목재',stone:'석재'}[resource];this.log(`${seller.name} 교역소 → ${buyer.name} 교역소: ${label} ${put.toFixed(1)} 거래`,false,'TRADE',{...row});return true;};

// AI: critical settlement food matters more than global total.
NS.VillageBrain.prototype.baseScores=function(v,w){const fd=v.criticalFoodReserveDays(),avg=v.foodReserveDays(),pop=v.population(),occ=pop/Math.max(1,v.capacity(w)),avgRel=v.averageVillageRelation(),rr=v.resourceRatios(w),front=v.expansionCandidates(w).length,settlers=v.availableSettlers().length,tradeP=v.tradePressure(w);let s={MAINTAIN:24,FOOD:15+Math.max(0,35-fd)*1.55,HOUSING:11+Math.max(0,occ-.85)*95,TRADE:11+tradeP*38+Math.max(0,avgRel)*.05,SECURITY:12+v.threat*1.3,EXPAND:10};s.EXPAND+=Math.max(0,pop-v.territory.size*3.2)*2.2+Math.max(0,.25-rr.food)*35+Math.min(6,front);if(fd<10){s.FOOD+=75;s.TRADE+=30;s.EXPAND-=70;}if(v.tradingPosts().length===0)s.TRADE=-100;if(v.expansionProject||front===0||pop<10||settlers<2)s.EXPAND=-130;if(v.gold<8)s.TRADE-=12;for(const k in s)s[k]+=(this.mods[k]||0);return s;};

// Bootstrap / serialization.
NS.V06={attachWorld(w,legacy=false){for(const t of w.map.tiles)ensureTileEconomy(t);for(const v of w.villages){if(legacy)distributeLegacy(v,w);else attachVillage(v,w);}return w;},capsForTile};
const oldSerializeV=NS.Village.prototype.serialize;NS.Village.prototype.serialize=function(){const d=oldSerializeV.call(this);d.tradeHistory=this.tradeHistory||[];d.logisticsStats=this.logisticsStats||{};delete d.food;delete d.wood;delete d.stone;return d;};
const oldWorldSerialize=NS.World.prototype.serialize;NS.World.prototype.serialize=function(){const d=oldWorldSerialize.call(this);d.version='0.6';return d;};
const oldFrom=NS.World.from;NS.World.from=function(d){if(d.version!=='0.6')throw new Error('V0.6 세이브만 불러올 수 있습니다.');const copy={...d,version:'0.5'};const w=oldFrom(copy);NS.V06.attachWorld(w,false);for(let i=0;i<w.villages.length;i++){w.villages[i].tradeHistory=d.villages[i]?.tradeHistory||[];w.villages[i].logisticsStats=d.villages[i]?.logisticsStats||{moves:0,foodMoved:0};}return w;};

const oldAdvance=NS.World.prototype.advanceOneDay;NS.World.prototype.advanceOneDay=function(){const before=this.ordinalDay();oldAdvance.call(this);if(before%5===0)this.processInternalLogistics();};
})(window.VSim);
